#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n % 2 != 0) return 0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        int balance = 0;
        bool valid = true;
        string candidate;
        for (int bit = n - 1; bit >= 0; --bit) {
            bool closing = (mask >> bit) & 1;
            candidate += closing ? ')' : '(';
            balance += closing ? -1 : 1;
            if (balance < 0) {
                valid = false;
                break;
            }
        }
        if (valid && balance == 0) cout << candidate << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;

pair<int, int> farthest(const vector<vector<int>>& graph, int start) {
    vector<int> distance(graph.size(), -1);
    queue<int> pending;
    pending.push(start);
    distance[start] = 0;
    int endpoint = start;
    while (!pending.empty()) {
        int vertex = pending.front();
        pending.pop();
        if (distance[vertex] > distance[endpoint]) endpoint = vertex;
        for (int next : graph[vertex]) {
            if (distance[next] != -1) continue;
            distance[next] = distance[vertex] + 1;
            pending.push(next);
        }
    }
    return {endpoint, distance[endpoint]};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> graph(n);
    for (int i = 0; i < n - 1; ++i) {
        int first, second;
        cin >> first >> second;
        --first;
        --second;
        graph[first].push_back(second);
        graph[second].push_back(first);
    }
    int endpoint = farthest(graph, 0).first;
    int diameter = farthest(graph, endpoint).second;
    cout << diameter + 1 << '\n';
}

