int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    string text;
    cin >> n >> k >> text;
    vector<array<int, 26>> nextPosition(n + 1);
    nextPosition[n].fill(n);
    for (int position = n - 1; position >= 0; --position) {
        nextPosition[position] = nextPosition[position + 1];
        nextPosition[position][text[position] - 'a'] = position;
    }
    string answer;
    int cursor = 0;
    for (int chosen = 0; chosen < k; ++chosen) {
        int remaining = k - chosen - 1;
        for (int letter = 0; letter < 26; ++letter) {
            int position = nextPosition[cursor][letter];
            if (position < n && n - position - 1 >= remaining) {
                answer += static_cast<char>('a' + letter);
                cursor = position + 1;
                break;
            }
        }
    }
    cout << answer << '\n';
}

