#include <bits/stdc++.h>
using namespace std;

struct DisjointSet {
    vector<int> parent;
    explicit DisjointSet(int size) : parent(size, -1) {}
    int root(int vertex) {
        return parent[vertex] < 0 ? vertex : parent[vertex] = root(parent[vertex]);
    }
    void unite(int first, int second) {
        first = root(first);
        second = root(second);
        if (first == second) return;
        if (parent[first] > parent[second]) swap(first, second);
        parent[first] += parent[second];
        parent[second] = first;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int height, width, queries;
    cin >> height >> width >> queries;
    DisjointSet components(height * width);
    vector<bool> active(height * width, false);
    const int rowStep[] = {-1, 1, 0, 0};
    const int columnStep[] = {0, 0, -1, 1};
    while (queries--) {
        int type, row, column;
        cin >> type >> row >> column;
        --row;
        --column;
        int cell = row * width + column;
        if (type == 1) {
            if (active[cell]) continue;
            active[cell] = true;
            for (int direction = 0; direction < 4; ++direction) {
                int nextRow = row + rowStep[direction];
                int nextColumn = column + columnStep[direction];
                if (nextRow < 0 || nextRow >= height || nextColumn < 0 || nextColumn >= width) continue;
                int neighbor = nextRow * width + nextColumn;
                if (active[neighbor]) components.unite(cell, neighbor);
            }
        } else {
            int otherRow, otherColumn;
            cin >> otherRow >> otherColumn;
            int other = (otherRow - 1) * width + otherColumn - 1;
            bool connected = active[cell] && active[other] && components.root(cell) == components.root(other);
            cout << (connected ? "Yes" : "No") << '\n';
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

using Edge = pair<int, long long>;
vector<long long> shortestPaths(const vector<vector<Edge>>& graph, int start) {
    const long long infinity = numeric_limits<long long>::max() / 4;
    vector<long long> distance(graph.size(), infinity);
    using State = pair<long long, int>;
    priority_queue<State, vector<State>, greater<State>> pending;
    distance[start] = 0;
    pending.push({0, start});
    while (!pending.empty()) {
        auto [currentDistance, vertex] = pending.top();
        pending.pop();
        if (currentDistance != distance[vertex]) continue;
        for (auto [next, cost] : graph[vertex]) {
            long long candidate = currentDistance + cost;
            if (candidate < distance[next]) {
                distance[next] = candidate;
                pending.push({candidate, next});
            }
        }
    }
    return distance;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<Edge>> graph(n);
    for (int i = 0; i < m; ++i) {
        int first, second;
        long long cost;
        cin >> first >> second >> cost;
        --first;
        --second;
        graph[first].push_back({second, cost});
        graph[second].push_back({first, cost});
    }
    auto fromStart = shortestPaths(graph, 0);
    auto fromEnd = shortestPaths(graph, n - 1);
    for (int vertex = 0; vertex < n; ++vertex) {
        cout << fromStart[vertex] + fromEnd[vertex] << '\n';
    }
}

