#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> graph(n), reversed(n);
    for (int i = 0; i < m; ++i) {
        int from, to;
        cin >> from >> to;
        --from;
        --to;
        graph[from].push_back(to);
        reversed[to].push_back(from);
    }
    vector<bool> seen(n, false);
    vector<int> finishOrder;
    for (int start = 0; start < n; ++start) {
        if (seen[start]) continue;
        vector<pair<int, int>> frames{{start, 0}};
        seen[start] = true;
        while (!frames.empty()) {
            int vertex = frames.back().first;
            int edgeIndex = frames.back().second;
            if (edgeIndex == static_cast<int>(graph[vertex].size())) {
                finishOrder.push_back(vertex);
                frames.pop_back();
                continue;
            }
            ++frames.back().second;
            int next = graph[vertex][edgeIndex];
            if (!seen[next]) {
                seen[next] = true;
                frames.push_back({next, 0});
            }
        }
    }
    fill(seen.begin(), seen.end(), false);
    long long answer = 0;
    for (auto it = finishOrder.rbegin(); it != finishOrder.rend(); ++it) {
        int start = *it;
        if (seen[start]) continue;
        vector<int> pending{start};
        seen[start] = true;
        long long componentSize = 0;
        while (!pending.empty()) {
            int vertex = pending.back();
            pending.pop_back();
            ++componentSize;
            for (int next : reversed[vertex]) {
                if (seen[next]) continue;
                seen[next] = true;
                pending.push_back(next);
            }
        }
        answer += componentSize * (componentSize - 1) / 2;
    }
    cout << answer << '\n';
}

